# apply_hunks.py <integration-sangam> <wt> <mine.txt> [--dry]
# For each of my files: re-diff the CURRENT integration file against my worktree file and apply only my hunks
# (targeted edits) onto the current file, keeping its line endings. Hunk filter: for files listed in ONLY_MARKED,
# only hunks whose new text contains one of the markers are applied (upstream hunks of other agents are kept).
# New files are created with CRLF (repository convention for checked-out text files). JSON realm files are skipped
# (regenerated by generate_realm.py in the tree).
import sys, os, difflib, hashlib

I, W, M = sys.argv[1:4]
DRY = '--dry' in sys.argv
ONLY_MARKED = {'sangam-rest/src/main/java/org/sangam/rest/adapter/operaton/OperatonOpsAdapter.java': ('SL-70',)}


def sha(b):
    return hashlib.sha256(b).hexdigest().upper()


for r in [l.strip() for l in open(M) if l.strip()]:
    if '/keycloak/realm/' in r:
        continue
    p, q = os.path.join(I, r), os.path.join(W, r)
    new = open(q, 'rb').read().replace(b'\r\n', b'\n').decode('utf-8')
    if not os.path.exists(p):
        out = new.replace('\n', '\r\n').encode('utf-8')
        print('CREATE', r, 'sha256', sha(out))
        if not DRY:
            open(p, 'wb').write(out)
        continue
    raw = open(p, 'rb').read()
    crlf = b'\r\n' in raw
    cur = raw.replace(b'\r\n', b'\n').decode('utf-8')
    a, b = cur.split('\n'), new.split('\n')
    ops = difflib.SequenceMatcher(None, a, b, autojunk=False).get_opcodes()
    markers = ONLY_MARKED.get(r)
    res, applied, kept = [], 0, 0
    for tag, i1, i2, j1, j2 in ops:
        if tag == 'equal':
            res += a[i1:i2]
            continue
        if markers is not None and not any(m in '\n'.join(b[j1:j2]) for m in markers):
            res += a[i1:i2]
            kept += 1
            continue
        res += b[j1:j2]
        applied += 1
    text = '\n'.join(res)
    out = (text.replace('\n', '\r\n') if crlf else text).encode('utf-8')
    print('EDIT  ', r, 'hunks applied', applied, 'upstream kept', kept, 'before', sha(raw)[:16], 'after', sha(out))
    if not DRY:
        open(p, 'wb').write(out)
